namespace SupportAgent.Core.Models;

public class Product { public int Id { get; set; } public Guid OrganizationId { get; set; } public string Sku { get; set; } = ""; public string Name { get; set; } = ""; public string? Description { get; set; } public decimal UnitPrice { get; set; } public bool IsActive { get; set; } = true; public DateTime CreatedAt { get; set; } public DateTime UpdatedAt { get; set; } public InventoryItem? Inventory { get; set; } }
public class Invoice { public int Id { get; set; } public Guid OrganizationId { get; set; } public int CustomerId { get; set; } public string InvoiceNumber { get; set; } = ""; public string Status { get; set; } = "Draft"; public DateTime IssueDate { get; set; } public DateTime? DueDate { get; set; } public decimal Subtotal { get; set; } public decimal TaxAmount { get; set; } public decimal DiscountAmount { get; set; } public decimal TotalAmount { get; set; } public DateTime CreatedAt { get; set; } public DateTime UpdatedAt { get; set; } public Customer Customer { get; set; } = null!; public ICollection<InvoiceItem> Items { get; set; } = []; public ICollection<Payment> Payments { get; set; } = []; }
public class InvoiceItem { public int Id { get; set; } public Guid OrganizationId { get; set; } public int InvoiceId { get; set; } public int? ProductId { get; set; } public string Description { get; set; } = ""; public decimal Quantity { get; set; } public decimal UnitPrice { get; set; } public decimal DiscountAmount { get; set; } public decimal TaxAmount { get; set; } public decimal LineTotal { get; set; } public Invoice Invoice { get; set; } = null!; public Product? Product { get; set; } }
public class Payment { public int Id { get; set; } public Guid OrganizationId { get; set; } public int InvoiceId { get; set; } public string PaymentReference { get; set; } = ""; public decimal Amount { get; set; } public DateTime PaymentDate { get; set; } public string? Method { get; set; } public string? Notes { get; set; } public DateTime CreatedAt { get; set; } public Invoice Invoice { get; set; } = null!; }
public class InventoryItem { public int Id { get; set; } public Guid OrganizationId { get; set; } public int ProductId { get; set; } public decimal QuantityOnHand { get; set; } public decimal ReorderLevel { get; set; } public DateTime UpdatedAt { get; set; } public Product Product { get; set; } = null!; }

public record InvoiceListItem(int Id, int CustomerId, string CustomerName, string InvoiceNumber, string Status, DateTime IssueDate, DateTime? DueDate, decimal TotalAmount, decimal PaidAmount, decimal OutstandingBalance);
public record InvoiceLineDetail(int Id, int? ProductId, string Description, decimal Quantity, decimal UnitPrice, decimal DiscountAmount, decimal TaxAmount, decimal LineTotal);
public record PaymentDetail(int Id, string PaymentReference, decimal Amount, DateTime PaymentDate, string? Method, string? Notes);
public record InvoiceDetail(int Id, int CustomerId, string CustomerName, string CustomerEmail, string InvoiceNumber, string Status, DateTime IssueDate, DateTime? DueDate, decimal Subtotal, decimal TaxAmount, decimal DiscountAmount, decimal TotalAmount, decimal PaidAmount, decimal OutstandingBalance, IReadOnlyList<InvoiceLineDetail> Items, IReadOnlyList<PaymentDetail> Payments);
public record CustomerBalance(int CustomerId, decimal TotalInvoiced, decimal TotalPaid, decimal OutstandingBalance);
public record InventoryStatus(int ProductId, string Sku, string ProductName, decimal QuantityOnHand, decimal ReorderLevel, bool LowStock);
public record SalesSummary(DateTime StartDate, DateTime EndDate, int InvoiceCount, decimal TotalSales, decimal TotalPaid, decimal OutstandingAmount);
